-- Set a value for the whole instance
ALTER SYSTEM SET work_mem = '64MB';
SELECT pg_reload_conf();

-- Which parameters need a restart?
SELECT name, setting, unit, pending_restart
FROM pg_settings
WHERE name IN ('shared_buffers', 'work_mem', 'max_connections', 'effective_cache_size');

-- Session-level override for one heavy query
SET work_mem = '256MB';
SELECT count(*) FROM large_report_query();
RESET work_mem;
